<script setup lang="ts">
import type {Item2View,ItemAction} from '../core/alpha2-types';
import type {Locale} from '../ui/i18n';
import type {Command} from '../core/types';
import {alpha2Text} from './i18n';
const props=defineProps<{items:Item2View[];locale:Locale;disabled:boolean;costs:Record<ItemAction,number>}>();
const emit=defineEmits<{command:[Command];action:[Item2View,ItemAction];note:[Item2View,Event]}>();
const t=(key:string)=>alpha2Text(props.locale,key);
</script>
<template><div class="bag-list"><article v-for="item in items" :key="item.id" class="bag-item" :data-item="item.id" :class="{equipped:item.equipped}"><div class="item-copy"><b>{{item.name[locale]}}</b><small>{{item.description?.[locale]??t('unknownDetails')}}</small><small>{{t(item.blessing??'bucUnknown')}} · {{t('durability')}} {{item.durability}}/6<span v-if="item.enchantment!==undefined"> · {{t('enchantment')}} {{item.enchantment}}</span><span v-if="item.charges!==undefined"> · {{t('charges')}} {{item.charges}}</span><span v-if="item.freshness"> · {{t(item.freshness)}}</span><span v-if="item.proof"> · {{t('proof')}}</span></small><small v-if="item.damage!==undefined||item.armor!==undefined">{{t('baseStats')}} · {{t('damage')}} {{item.damage??0}} / {{t('armor')}} {{item.armor??0}}</small><small v-if="item.time">{{t('actionTime')}} {{item.time}} · {{t('range')}} {{item.range}}</small><small v-if="item.equipped">{{t('equippedTag')}} · {{t(item.equipped)}}</small><label v-if="!item.definition||item.note" class="item-note">{{t('note')}}<input :value="item.note" maxlength="120" :disabled="disabled" :aria-label="`${t('note')} ${item.id}`" @change="emit('note',item,$event)" /></label></div><div class="item-actions"><button v-for="action in item.equipped?[]:item.actions" :key="action" :disabled="disabled" :data-action="action" @click="emit('action',item,action)">{{t(action)}} · {{costs[action]}}</button><button v-if="item.equipped" :disabled="disabled" @click="emit('command',`unequip:${item.equipped}` as Command)">{{t('unequip')}}</button><button v-else :disabled="disabled" @click="emit('command',`drop:${item.id}`)">{{t('drop')}}</button></div></article></div></template>
